const C=window.SCHOOL_CATALOG;
const APP=document.getElementById('app');
const STORAGE='school-simulator-cards-v3';
let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE))||{}}catch{}
let old={};try{old=JSON.parse(localStorage.getItem('school-simulator-practice-v1'))||{}}catch{}
if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};
if(!old||typeof old!=='object'||Array.isArray(old))old={};
if(!saved.results||typeof saved.results!=='object'||Array.isArray(saved.results))saved.results={};
const state={page:'home',grade:[5,6,7,8,9].includes(Number(saved.grade||old.grade))?Number(saved.grade||old.grade):8,subject:'all',topic:null,card:0,photos:[],scanText:'',scanTasks:[],marked:new Set(),recommendations:[],analysisScope:'',practice:null,results:saved.results||{}};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topic=id=>C.byId(id),subject=id=>C.subjectById(id);
let save=()=>localStorage.setItem(STORAGE,JSON.stringify({grade:state.grade,results:state.results}));
const result=id=>state.results[id]||{cards:{}};
const finished=(id,i)=>Boolean(result(id).cards?.[i]?.done);
const cardCount=id=>Object.values(result(id).cards||{}).filter(x=>x.done).length;
const xp=()=>Object.values(state.results).reduce((sum,r)=>sum+Object.values(r.cards||{}).reduce((n,c)=>n+(c.done?15+(c.firstTry?5:0):0),0),0);
const level=()=>Math.floor(xp()/120)+1;
const studied=()=>Object.keys(state.results).filter(id=>cardCount(id)>0).length;
const allCards=()=>Object.values(state.results).reduce((n,r)=>n+Object.values(r.cards||{}).filter(c=>c.done).length,0);
const topicCountText=n=>`${n} ${n%100>=11&&n%100<=14?'тем':n%10===1?'тема':n%10>=2&&n%10<=4?'темы':'тем'}`;
let toastTimer;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function head(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`}
function gradeButtons(){return `<section class="grade-selector" aria-label="Выбор класса"><div class="grade-selector-heading"><span class="eyebrow">ТВОЙ КЛАСС</span><span>Выбери, чтобы увидеть предметы и темы</span></div><div class="grade-bar" role="group" aria-label="Выбрать класс">${[5,6,7,8,9].map(g=>`<button type="button" class="chip ${state.grade===g?'active':''}" data-grade="${g}" aria-pressed="${state.grade===g}"><strong>${g}</strong><span>класс</span><i aria-hidden="true">${state.grade===g?'✓':'↗'}</i></button>`).join('')}</div></section>`}

function subjectCard(s){const count=C.topics.filter(t=>t.subject===s.id&&t.grade===state.grade).length;return `<button class="card subject-card" data-subject="${s.id}"><span class="subject-icon" style="background:${s.tone}">${s.icon}</span><h3>${s.name}</h3><small>${count?`${topicCountText(count)} с карточками`:'Задания готовятся'}</small><span class="subject-foot">${count?'Открыть раздел →':'Посмотреть раздел →'}</span></button>`}
function topicCard(t){const count=cardCount(t.id),s=subject(t.subject);return `<button class="card poster-card" data-open="${t.id}" aria-label="Открыть тему ${t.title}"><span class="poster-art poster-${t.subject}"><span class="poster-symbol">${s.icon}</span><span class="poster-spark">✦</span></span><span class="poster-info"><small>${t.grade} класс · ${t.unit}</small><strong>${t.title}</strong><span class="poster-progress"><i style="width:${count*25}%"></i></span><em>${count} из 4 карточек</em></span></button>`}
function home(){const subjects=C.subjects.filter(s=>s.grades.includes(state.grade));const picks=state.recommendations.length?state.recommendations.map(r=>topic(r.id)).filter(Boolean):C.topics.filter(t=>t.grade===state.grade).slice(0,4);return `<section class="hero"><div class="hero-copy"><div class="eyebrow">ПОНЯТНО</div><h1>Разбирайся<br>шаг за шагом.</h1><p>Разбери работу, найди трудную тему и открой короткие карточки. Решай прямо здесь и возвращайся к основе, когда нужно.</p><button class="btn btn-orange" data-go="scan">Разобрать работу →</button></div><div class="hero-visual"><img src="raccoon.svg" alt="Енот с книгой"><span class="hero-note">Решаем шаг за шагом</span></div></section><div class="quick-grid home-quick"><div class="card quick-card primary"><span class="quick-icon">▣</span><h3>Есть работа с ошибками?</h3><p>Фото контрольной, самостоятельной или домашней работы.</p><button class="btn-link" data-go="scan">Найти темы →</button></div><div class="card quick-card"><span class="quick-number">${allCards()}</span><h3>карточек решено</h3><p>Прогресс остаётся в этом браузере.</p><button class="btn-link" data-go="profile">Мои результаты →</button></div><div class="card quick-card"><span class="quick-number">${level()}</span><h3>уровень</h3><p>За завершённые карточки начисляется опыт.</p><button class="btn-link" data-go="catalog">Выбрать тему →</button></div></div><div class="section-title"><h2>Предметы ${state.grade} класса</h2><button data-go="catalog">Все предметы →</button></div>${gradeButtons()}<div class="subject-grid">${subjects.map(subjectCard).join('')}</div><div class="section-title"><h2>${state.recommendations.length?'Маршрут после разбора':'Карточки для старта'}</h2><button data-go="catalog">Все темы →</button></div><div class="poster-grid">${picks.map(topicCard).join('')}</div>`}
function catalog(){const subjects=C.subjects.filter(s=>s.grades.includes(state.grade));const chosen=state.subject==='all'?subjects:subjects.filter(s=>s.id===state.subject);const topics=C.topics.filter(t=>t.grade===state.grade&&(state.subject==='all'||t.subject===state.subject));const units=[...new Set(topics.map(t=>t.unit))];return `${head('БИБЛИОТЕКА ЗАДАНИЙ','Выбери предмет и тему','Открой тему, затем любую карточку маршрута. Все упражнения решаются внутри платформы.')}${gradeButtons()}<div class="filter-bar"><button class="chip ${state.subject==='all'?'active':''}" data-filter="all">Все предметы</button>${subjects.map(s=>`<button class="chip ${state.subject===s.id?'active':''}" data-filter="${s.id}">${s.name}</button>`).join('')}</div><div class="subject-grid">${chosen.map(subjectCard).join('')}</div>${topics.length?units.map(unit=>`<section class="catalog-unit"><div class="section-title"><h2>${unit}</h2><span class="muted">${topicCountText(topics.filter(t=>t.unit===unit).length)}</span></div><div class="poster-grid">${topics.filter(t=>t.unit===unit).map(topicCard).join('')}</div></section>`).join(''):`<div class="empty">Карточки по этому предмету ещё не подготовлены. Выбери другой раздел.</div>`}<div class="browse-note" style="margin-top:28px">Подробно заполнены крупные темы русского языка 5 класса из присланной программы. Для остальных предметов и классов банк расширяется поэтапно.</div>`}
const cardNames=['Знакомство','Найди правило','Примени','Проверь себя'];
const cardMarks=['✦','◈','✎','✓'];
function topicPage(){const t=topic(state.topic);if(!t)return catalog();const s=subject(t.subject),count=cardCount(t.id),base=t.prereq.map(topic).filter(Boolean);return `<div class="crumb"><button data-go="catalog">Предметы</button><span>›</span><button data-subject="${t.subject}">${s.name}</button><span>›</span><span>${t.title}</span></div><section class="topic-hero"><div><span class="eyebrow">${s.name.toUpperCase()} · ${t.grade} КЛАСС</span><h1>${t.title}</h1><p>${t.learn}</p><div class="topic-hero-progress"><span>${count} из 4 карточек пройдено</span><span class="poster-progress"><i style="width:${count*25}%"></i></span></div></div><span class="topic-hero-symbol">${s.icon}</span></section><div class="section-title"><h2>Маршрут по теме</h2><span class="muted">Выбери карточку и реши задание</span></div><div class="route-grid">${[0,1,2,3].map(i=>`<button class="route-card ${finished(t.id,i)?'completed':''}" data-card="${i}"><span class="route-top"><span>Карточка ${i+1}</span><b>${finished(t.id,i)?'✓':String(i+1).padStart(2,'0')}</b></span><span class="route-illustration"><span>${cardMarks[i]}</span></span><strong>${cardNames[i]}</strong><small>${finished(t.id,i)?'Пройдено · можно повторить':'Открыть задание →'}</small></button>`).join('')}</div>${base.length?`<section class="base-section"><div class="section-title"><h2>Основа, к которой можно вернуться</h2></div><div class="poster-grid">${base.map(topicCard).join('')}</div></section>`:''}`}
function choiceOptions(q,p){return `<div class="game-options ${q.kind==='multi'?'game-multi':''}">${q.options.map((option,i)=>{const selected=q.kind==='multi'?p.selected.includes(String(i)):p.selected===String(i);return `<button class="game-option ${selected?'selected':''}" data-answer="${i}" ${p.answered?'disabled':''}><span class="answer-index">${selected?'✓':String.fromCharCode(65+i)}</span><span>${esc(option)}</span></button>`}).join('')}</div>`}
function orderOptions(q,p){return `<div class="order-panel"><div class="order-label">Выбранный порядок</div><div class="order-picked">${p.order.length?p.order.map((id,j)=>`<button data-unpick="${id}" ${p.answered?'disabled':''}><b>${j+1}</b>${esc(q.options[Number(id)])}<span>×</span></button>`).join(''):'<span class="order-empty">Нажимай на шаги ниже по порядку</span>'}</div><div class="order-label">Шаги</div><div class="order-pool">${q.options.map((x,i)=>p.order.includes(String(i))?'':`<button data-pick="${i}" ${p.answered?'disabled':''}>${esc(x)} <span>＋</span></button>`).join('')}</div></div>`}
function practice(){const p=state.practice;if(!p)return catalog();const t=topic(p.topic),q=p.question;const s=subject(t.subject);return `<div class="game-shell"><div class="game-header"><button class="game-back" data-open="${t.id}">← Назад к карточкам</button><div class="game-dots">${[0,1,2,3].map(i=>`<span class="${i===p.card?'current':finished(t.id,i)?'complete':''}"></span>`).join('')}</div><div class="game-count">${p.card+1} / 4</div></div><div class="game-intro"><span class="eyebrow">${s.name.toUpperCase()} · ${t.title}</span><h1>${q.kind==='multi'?'Выбери все подходящие ответы':q.kind==='order'?'Расставь шаги по порядку':q.kind==='number'?'Найди число':'Выбери ответ'}</h1><p>${esc(q.prompt)}</p></div><div class="game-stage">${q.kind==='choice'||q.kind==='multi'?choiceOptions(q,p):q.kind==='order'?orderOptions(q,p):`<label class="field-label" for="numberAnswer">Ответ</label><input class="input answer-number" id="numberAnswer" inputmode="decimal" placeholder="Введи число" value="${esc(p.numeric)}" ${p.answered?'disabled':''}>`}</div><div class="game-actions">${p.answered?`<button class="btn btn-orange" id="finishCard">Завершить карточку →</button>`:`<button class="btn btn-orange" id="checkAnswer">Проверить</button><button class="btn btn-light" id="hintButton">Подсказка</button>${p.attempts>=2?'<button class="btn btn-light" id="showSolution">Показать решение</button>':''}`}</div>${p.feedback?`<div class="feedback ${p.feedback.good?'good':'try'}" role="status"><strong>${esc(p.feedback.title)}</strong>${esc(p.feedback.text)}</div>`:''}<div class="game-footer"><span class="game-mascot"><img src="raccoon.svg" alt=""><b>${q.context||'Всё получится'}</b></span><span>Карточка ${p.card+1}: ${cardNames[p.card]}</span></div></div>`}
function done(){const p=state.practice;if(!p)return catalog();const t=topic(p.topic),count=cardCount(t.id);return `${head('КАРТОЧКА ЗАВЕРШЕНА',p.firstTry?'Получилось с первого раза!':'Шаг сделан',`Пройдено ${count} из 4 карточек темы «${t.title}».`)}<div class="card result-summary"><div class="done-emblem">${p.firstTry?'★':'✓'}</div><h2>${p.firstTry?'Отличный ход':'Ошибки помогли разобраться'}</h2><p>${p.firstTry?'Ты получил опыт за точный ответ.':`Пояснение доступно в карточке. Попробуй её ещё раз после остальных.`}</p><div class="task-actions">${p.card<3?`<button class="btn btn-orange" data-nextcard="${p.card+1}">Следующая карточка →</button>`:''}<button class="btn btn-light" data-open="${t.id}">Маршрут темы</button><button class="btn btn-light" data-go="profile">Мой прогресс</button></div></div>`}
function scan(){return `${head('РАЗБОР РАБОТЫ','Покажи, где было трудно','Загрузи фото контрольной, самостоятельной или домашней работы. Проверь текст и отметь номера с ошибками.') }<div class="scan-layout"><section class="card scan-panel"><h2>1. Добавь работу</h2><p>Можно выбрать до четырёх фотографий.</p><label class="upload-zone" for="photoInput"><strong>＋ Сфотографировать или выбрать файлы</strong><small>JPG, PNG, WEBP · до 8 МБ каждый</small><input id="photoInput" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" multiple></label><div class="upload-previews">${state.photos.map(x=>`<img src="${x.url}" alt="Загруженная страница работы">`).join('')}</div><div class="inline-note">Распознавание идёт в браузере. Фото не отправляется на сервер; для первого запуска скачивается OCR-модель.</div><div class="task-actions"><button class="btn btn-blue" id="ocrButton" ${state.photos.length?'':'disabled'}>Распознать фото</button></div><div id="ocrStatus" class="inline-note" role="status"></div><label class="field-label" for="scanText">2. Проверь или введи текст заданий</label><textarea id="scanText" class="textarea" placeholder="1. Реши уравнение…&#10;2. Найди силу тока…">${esc(state.scanText)}</textarea><div class="task-actions"><button class="btn btn-orange" id="splitWork">Далее: отметить ошибки →</button><button class="btn btn-light" data-scan-example>Показать пример</button></div></section><aside class="card scan-guide"><h3>Как работает маршрут</h3><ol><li>Распознаём текст.</li><li>Ты исправляешь неточности.</li><li>Отмечаешь задания с ошибками.</li><li>Система предлагает темы и базовые навыки.</li><li>Каждую тему можно открыть и решить здесь.</li></ol><p>По одному условию нельзя узнать, где ученик ошибся. Без отметок мы покажем только темы для проверки.</p></aside></div>${state.scanTasks.length?scanTasksHtml():''}${state.recommendations.length?recommendationsHtml():''}`}
function scanTasksHtml(){return `<section class="card scan-stage" id="scanTasksSection"><h2>3. Где были ошибки?</h2><p>Отметь проверенные задания с ошибками. Без отметок вывод будет предварительным.</p><div class="work-list">${state.scanTasks.map((task,i)=>`<label class="work-row"><input type="checkbox" data-mark="${i}" ${state.marked.has(i)?'checked':''}><div><b>Задание ${i+1}</b><span>${esc(task).slice(0,500)}</span></div></label>`).join('')}</div><button class="btn btn-orange" id="analyzeWork">Показать темы →</button></section>`}
function recommendationsHtml(){return `<section class="card scan-stage" id="recommendationsSection"><div class="eyebrow">МАРШРУТ ПОВТОРЕНИЯ</div><h2>Темы для проверки</h2><p>${state.analysisScope==='marked'?'По отмеченным заданиям найдены возможные темы. Проверь их на новых карточках.':'Ошибочные номера не отмечены: это темы по условиям работы, а не доказанные пробелы.'}</p><div class="recommendations">${state.recommendations.map((r,i)=>{const t=topic(r.id);return `<article class="card rec-card"><span class="rec-rank">${i+1}</span><div><span class="badge ${r.basis?'sand':''}">${r.basis?`Возможная основа · ${t.grade} класс`:`Тема · ${t.grade} класс`}</span><h3>${t.title}</h3><p>${r.basis?`Может понадобиться перед темой «${topic(r.basis)?.title||''}».`:t.learn}</p></div><button class="btn btn-small ${r.basis?'btn-light':'btn-orange'}" data-open="${t.id}">Открыть карточки</button></article>`}).join('')}</div></section>`}
function splitWork(){state.scanText=document.getElementById('scanText')?.value.trim()||state.scanText;if(!state.scanText){toast('Сначала добавь текст заданий');return}state.scanTasks=state.scanText.split(/\n(?=\s*(?:№\s*)?\d{1,2}[.)]\s)/).map(x=>x.trim()).filter(Boolean).slice(0,20);state.marked=new Set();state.recommendations=[];render();document.getElementById('scanTasksSection')?.scrollIntoView({behavior:'smooth'})}
function analyzeWork(){const selected=state.marked.size?[...state.marked].map(i=>state.scanTasks[i]).filter(Boolean):state.scanTasks;const hits=new Map();for(const line of selected){const lower=line.toLowerCase();for(const t of C.topics){let score=t.keywords.reduce((n,k)=>n+(lower.includes(k)?2:0),0);if(t.id==='quadratic'&&/[xх]\s*[²^]/i.test(line))score+=2;if(score)hits.set(t.id,(hits.get(t.id)||0)+score)}}const ranked=[...hits].sort((a,b)=>b[1]-a[1]).slice(0,3);if(!ranked.length){toast('Не получилось определить тему. Уточни текст или выбери предмет вручную.');return}let recs=[],seen=new Set();for(const [id] of ranked){if(!seen.has(id)){recs.push({id});seen.add(id)}for(const p of topic(id).prereq.slice(0,2))if(!seen.has(p)){recs.push({id:p,basis:id});seen.add(p)}}state.recommendations=recs.slice(0,8);state.analysisScope=state.marked.size?'marked':'all';render();document.getElementById('recommendationsSection')?.scrollIntoView({behavior:'smooth'})}
let ocrPromise;
function loadOCR(){return Promise.reject(new Error('Модуль локального OCR не загружен'));}
async function recognizePhotos(){toast('Модуль локального OCR не загружен. Обнови страницу.');}
function profile(){const entries=C.topics.filter(t=>cardCount(t.id)).sort((a,b)=>(result(b.id).updated||0)-(result(a.id).updated||0));return `${head('ЛИЧНЫЙ КАБИНЕТ','Мой маршрут','Здесь видны завершённые карточки, опыт и темы для повторения.') }<div class="card profile-top"><div><div class="eyebrow">ПРОГРЕСС</div><h1>Уровень ${level()}</h1><p>${xp()} опыта за работу с карточками</p></div><div class="level-badge">${level()}</div></div><div class="stat-grid"><div class="card stat-card"><strong>${studied()}</strong><span>темы начаты</span></div><div class="card stat-card"><strong>${allCards()}</strong><span>карточек пройдено</span></div><div class="card stat-card"><strong>${xp()}</strong><span>баллов опыта</span></div></div><div class="section-title"><h2>Мои темы</h2><button data-go="catalog">Каталог →</button></div>${entries.length?`<div class="poster-grid">${entries.map(topicCard).join('')}</div>`:'<div class="empty">Выбери тему и реши первую карточку — результат появится здесь.</div>'}`}
function render(){const pages={home,catalog,topic:topicPage,practice,done,scan,profile};APP.innerHTML=(pages[state.page]||home)();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===state.page||(['topic','practice','done'].includes(state.page)&&a.dataset.nav==='catalog')));document.getElementById('headerLevel').textContent=`${level()} уровень`;document.title=`${{home:'Главная',catalog:'Предметы',topic:'Карточки темы',practice:'Задание',done:'Итог',scan:'Разбор работы',profile:'Мой кабинет'}[state.page]||'Понятно'} — Понятно`}
function go(page){state.page=page;document.querySelector('.header-nav').classList.remove('open');document.getElementById('menuToggle').setAttribute('aria-expanded','false');render();const hash=page==='guide'&&state.topic?'#guide='+encodeURIComponent(state.topic):page==='topic'&&state.topic?'#topic='+encodeURIComponent(state.topic):page==='practice'&&state.practice?'#card='+encodeURIComponent(state.topic)+':'+state.card:'#page='+page;if(location.hash!==hash)history.pushState(null,'',hash);window.scrollTo({top:0,behavior:'smooth'})}
function openTopic(id){if(!topic(id))return;state.topic=id;state.grade=topic(id).grade;save();go('topic')}
function startCard(id,index){const t=topic(id),question=C.questions(id)?.[index];if(!t||!question)return;state.topic=id;state.grade=t.grade;state.card=index;state.practice={topic:id,card:index,question,selected:question.kind==='multi'?[]:null,order:[],numeric:'',answered:false,attempts:0,firstTry:false,feedback:null};save();go('practice')}
function checkAnswer(){const p=state.practice;if(!p||p.answered)return;const q=p.question;let correct=false,hasAnswer=false;if(q.kind==='choice'){hasAnswer=p.selected!==null;correct=p.selected===q.answer}else if(q.kind==='multi'){hasAnswer=p.selected.length>0;correct=[...p.selected].sort().join(',')===[...q.answer].sort().join(',')}else if(q.kind==='order'){hasAnswer=p.order.length===q.options.length;correct=p.order.join(',')===q.answer.join(',')}else{const value=document.getElementById('numberAnswer')?.value.trim().replace(',','.');hasAnswer=value!==''&&value!=null;correct=hasAnswer&&Number.isFinite(Number(value))&&Number(value)===Number(q.answer)}if(!hasAnswer){toast(q.kind==='order'?'Расставь все шаги':'Сначала выбери или введи ответ');return}p.attempts++;if(correct){p.firstTry=p.attempts===1;p.answered=true;p.feedback={good:true,title:'Верно!',text:q.explain}}else{p.feedback={good:false,title:'Попробуй ещё',text:q.hint}}render()}
function finishCard(){const p=state.practice;if(!p||!p.answered)return;const old=result(p.topic),cards={...(old.cards||{})};cards[p.card]={done:true,firstTry:Boolean(cards[p.card]?.firstTry||p.firstTry),attempts:p.attempts};state.results[p.topic]={cards,updated:Date.now()};save();go('done')}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();go(nav.dataset.nav);return}const logo=e.target.closest('.logo');if(logo){e.preventDefault();go('home');return}const goBtn=e.target.closest('[data-go]');if(goBtn){go(goBtn.dataset.go);return}const grade=e.target.closest('[data-grade]');if(grade){state.grade=Number(grade.dataset.grade);state.subject='all';save();render();return}const filter=e.target.closest('[data-filter]');if(filter){state.subject=filter.dataset.filter;render();return}const s=e.target.closest('[data-subject]');if(s){state.subject=s.dataset.subject;go('catalog');return}const open=e.target.closest('[data-open]');if(open){openTopic(open.dataset.open);return}const card=e.target.closest('[data-card]');if(card){startCard(state.topic,Number(card.dataset.card));return}const next=e.target.closest('[data-nextcard]');if(next){startCard(state.topic,Number(next.dataset.nextcard));return}const answer=e.target.closest('[data-answer]');if(answer&&state.practice&&!state.practice.answered){const p=state.practice,id=answer.dataset.answer;if(p.question.kind==='multi')p.selected=p.selected.includes(id)?p.selected.filter(x=>x!==id):[...p.selected,id];else p.selected=id;render();return}const pick=e.target.closest('[data-pick]');if(pick&&state.practice&&!state.practice.answered){state.practice.order.push(pick.dataset.pick);render();return}const unpick=e.target.closest('[data-unpick]');if(unpick&&state.practice&&!state.practice.answered){state.practice.order=state.practice.order.filter(x=>x!==unpick.dataset.unpick);render();return}if(e.target.id==='checkAnswer'){checkAnswer();return}if(e.target.id==='hintButton'){const p=state.practice;p.feedback={good:false,title:'Подсказка',text:p.question.hint};render();return}if(e.target.id==='showSolution'){const p=state.practice;p.answered=true;p.feedback={good:false,title:'Разбор',text:p.question.explain};render();return}if(e.target.id==='finishCard'){finishCard();return}if(e.target.id==='splitWork'){splitWork();return}if(e.target.id==='analyzeWork'){analyzeWork();return}if(e.target.id==='ocrButton'){recognizePhotos();return}if(e.target.closest('[data-scan-example]')){state.scanText='1. Тележка массой 3 кг получает ускорение 4 м/с². Найди силу по второму закону Ньютона.\n2. Реши квадратное уравнение x² = 25.\n3. Найди силу тока при напряжении 12 В и сопротивлении 4 Ом по закону Ома.';state.scanTasks=[];state.recommendations=[];render();toast('Пример добавлен')}});
document.addEventListener('change',e=>{if(e.target.id==='photoInput'){const files=[...e.target.files].filter(f=>['image/jpeg','image/png','image/webp'].includes(f.type)&&f.size<=8*1024*1024);for(const f of files.slice(0,4-state.photos.length))state.photos.push({file:f,url:URL.createObjectURL(f)});if(files.length){state.scanText='';state.scanTasks=[];state.marked=new Set();state.recommendations=[]}render();toast(state.photos.length?'Фото добавлено. Можно распознать текст.':'Нужен JPG, PNG или WEBP до 8 МБ.')}if(e.target.dataset.mark!==undefined){const i=Number(e.target.dataset.mark);e.target.checked?state.marked.add(i):state.marked.delete(i)}});
document.addEventListener('input',e=>{if(e.target.id==='scanText')state.scanText=e.target.value;if(e.target.id==='numberAnswer'&&state.practice)state.practice.numeric=e.target.value});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='numberAnswer'){e.preventDefault();checkAnswer()}});
document.getElementById('menuToggle').addEventListener('click',e=>{const open=document.querySelector('.header-nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});
let hash='';try{hash=decodeURIComponent(location.hash.slice(1));}catch{}
if(hash.startsWith('topic=')&&topic(hash.slice(6))){state.topic=hash.slice(6);state.page='topic'}
else if(hash.startsWith('card=')){const [id,index]=hash.slice(5).split(':');if(topic(id)&&C.questions(id)?.[Number(index)])startCard(id,Number(index))}
else{const first=hash.startsWith('page=')?hash.slice(5):hash;if(['home','catalog','scan','profile'].includes(first))state.page=first}
render();

